macro_rules! deps {
    () => {
        Literal!();
        ExtractKind!();
        Seq!();
        Hir!();
    };
}

macro_rules! Extractor {
    () => {
        deps!();
        # [doc = " Extracts prefix or suffix literal sequences from [`Hir`] expressions."] # [doc = ""] # [doc = " Literal extraction is based on the following observations:"] # [doc = ""] # [doc = " * Many regexes start with one or a small number of literals."] # [doc = " * Substring search for literals is often much faster (sometimes by an order"] # [doc = " of magnitude) than a regex search."] # [doc = ""] # [doc = " Thus, in many cases, one can search for literals to find candidate starting"] # [doc = " locations of a match, and then only run the full regex engine at each such"] # [doc = " location instead of over the full haystack."] # [doc = ""] # [doc = " The main downside of literal extraction is that it can wind up causing a"] # [doc = " search to be slower overall. For example, if there are many matches or if"] # [doc = " there are many candidates that don't ultimately lead to a match, then a"] # [doc = " lot of overhead will be spent in shuffling back-and-forth between substring"] # [doc = " search and the regex engine. This is the fundamental reason why literal"] # [doc = " optimizations for regex patterns is sometimes considered a \"black art.\""] # [doc = ""] # [doc = " # Look-around assertions"] # [doc = ""] # [doc = " Literal extraction treats all look-around assertions as-if they match every"] # [doc = " empty string. So for example, the regex `\\bquux\\b` will yield a sequence"] # [doc = " containing a single exact literal `quux`. However, not all occurrences"] # [doc = " of `quux` correspond to a match a of the regex. For example, `\\bquux\\b`"] # [doc = " does not match `ZquuxZ` anywhere because `quux` does not fall on a word"] # [doc = " boundary."] # [doc = ""] # [doc = " In effect, if your regex contains look-around assertions, then a match of"] # [doc = " an exact literal does not necessarily mean the regex overall matches. So"] # [doc = " you may still need to run the regex engine in such cases to confirm the"] # [doc = " match."] # [doc = ""] # [doc = " The precise guarantee you get from a literal sequence is: if every literal"] # [doc = " in the sequence is exact and the original regex contains zero look-around"] # [doc = " assertions, then a preference-order multi-substring search of those"] # [doc = " literals will precisely match a preference-order search of the original"] # [doc = " regex."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " This shows how to extract prefixes:"] # [doc = ""] # [doc = " ```"] # [doc = " use regex_syntax::{hir::literal::{Extractor, Literal, Seq}, parse};"] # [doc = ""] # [doc = " let hir = parse(r\"(a|b|c)(x|y|z)[A-Z]+foo\")?;"] # [doc = " let got = Extractor::new().extract(&hir);"] # [doc = " // All literals returned are \"inexact\" because none of them reach the"] # [doc = " // match state."] # [doc = " let expected = Seq::from_iter(["] # [doc = "     Literal::inexact(\"ax\"),"] # [doc = "     Literal::inexact(\"ay\"),"] # [doc = "     Literal::inexact(\"az\"),"] # [doc = "     Literal::inexact(\"bx\"),"] # [doc = "     Literal::inexact(\"by\"),"] # [doc = "     Literal::inexact(\"bz\"),"] # [doc = "     Literal::inexact(\"cx\"),"] # [doc = "     Literal::inexact(\"cy\"),"] # [doc = "     Literal::inexact(\"cz\"),"] # [doc = " ]);"] # [doc = " assert_eq!(expected, got);"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " This shows how to extract suffixes:"] # [doc = ""] # [doc = " ```"] # [doc = " use regex_syntax::{"] # [doc = "     hir::literal::{Extractor, ExtractKind, Literal, Seq},"] # [doc = "     parse,"] # [doc = " };"] # [doc = ""] # [doc = " let hir = parse(r\"foo|[A-Z]+bar\")?;"] # [doc = " let got = Extractor::new().kind(ExtractKind::Suffix).extract(&hir);"] # [doc = " // Since 'foo' gets to a match state, it is considered exact. But 'bar'"] # [doc = " // does not because of the '[A-Z]+', and thus is marked inexact."] # [doc = " let expected = Seq::from_iter(["] # [doc = "     Literal::exact(\"foo\"),"] # [doc = "     Literal::inexact(\"bar\"),"] # [doc = " ]);"] # [doc = " assert_eq!(expected, got);"] # [doc = ""] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [derive (Clone , Debug)] pub struct Extractor { kind : ExtractKind , limit_class : usize , limit_repeat : usize , limit_literal_len : usize , limit_total : usize , }
    };
}

Extractor!()